const triggerRow = $('Google Sheets - Watch Properties').first().json;
const eventTypeItems = $input.all().map(i => i.json);

function unwrapApiList(items) {
  const out = [];
  for (const item of items) {
    if (!item) continue;
    const candidates = [item.data, item.eventTypes, item.items, item.results, item];
    let picked = null;
    for (const c of candidates) {
      if (Array.isArray(c)) { picked = c; break; }
    }
    if (picked) out.push(...picked);
  }
  return out;
}

const eventTypes = unwrapApiList(eventTypeItems);

const s = (v) => String(v ?? '').trim();
const lower = (v) => s(v).toLowerCase();
const isDateLike = (v) => /^(\d{4}-\d{2}-\d{2}|\d{1,2}\/\d{1,2}\/\d{4})/.test(s(v));
const slugify = (input) => s(input)
  .toLowerCase()
  .replace(/https?:\/\//g, '')
  .split('/')
  .pop()
  .replace(/[^a-z0-9]+/g, '-')
  .replace(/^-+|-+$/g, '');
const titleCase = (input) => s(input)
  .split(/\s+/)
  .filter(Boolean)
  .map(part => part.charAt(0).toUpperCase() + part.slice(1))
  .join(' ');
const cleanText = (value, fallback) => {
  const v = s(value);
  if (!v || isDateLike(v) || ['updated', 'provisioned', 'subscribed', 'active', 'inactive'].includes(lower(v))) return fallback;
  return v;
};
const parseDuration = (value, fallback = 30) => {
  const m = s(value).match(/\d+/);
  const n = m ? parseInt(m[0], 10) : NaN;
  return Number.isFinite(n) && n > 0 ? n : fallback;
};

const templateSlug = '102-braeford';
const templateEvent =
  eventTypes.find(e => slugify(e.slug) === templateSlug) ||
  eventTypes.find(e => slugify(e.title).includes('102-braeford'));
if (!templateEvent) throw new Error('Template event type "102-braeford" not found in Cal.com');

const templateScheduleId =
  templateEvent.scheduleId ?? templateEvent.schedule_id ??
  templateEvent.schedule?.id ?? templateEvent.schedule?.scheduleId ?? null;

const row = triggerRow;
const fallbackBase = titleCase(row.owner_label || row.street_address || row.property_key || 'Property');
const rowTitleBase = cleanText(row.cal_event_type_name, '');
const title = /walk-through/i.test(rowTitleBase)
  ? rowTitleBase
  : (rowTitleBase ? `${rowTitleBase} Walk-Through` : `${fallbackBase} Walk-Through`);

const slug = slugify(row.cal_link || row.property_key || title);
const existing = eventTypes.find(e => slugify(e.slug) === slug);
const description = cleanText(row.cal_description, '30 minute walk-through');
const duration = parseDuration(row.cal_duration_minutes, 30);
const address = cleanText(row.street_address, cleanText(row.owner_label, fallbackBase));
const calLink = cleanText(row.cal_link, `cal.com/rentingfreedom/${slug}`);

return [{
  json: {
    ...row,
    cal_link: calLink,
    cal_event_type_id: existing?.id || '',
    method: existing ? 'PATCH' : 'POST',
    url: existing ? `https://api.cal.com/v2/event-types/${existing.id}` : 'https://api.cal.com/v2/event-types',
    body: {
      lengthInMinutes: duration,
      title,
      slug,
      description,
      ...(templateScheduleId ? { scheduleId: templateScheduleId } : {}),
      locations: [{ type: 'address', address, public: true }],
      bookingFields: [{ type: 'name', required: true, isDefault: true, slug: 'name' }],
      disableGuests: true,
      bookingRequiresAuthentication: false,
      lockTimeZoneToggleOnBookingPage: true,
      minimumBookingNotice: 0,
      beforeEventBuffer: 0,
      afterEventBuffer: 0,
      slotInterval: Math.min(duration, 30),
      customName: title,
    },
  }
}];

const buildData = $('Build Cal.com Body').first().json;
const calResponse = $('Cal.com - Create Event Type').first().json;
const adminResponse = $input.first().json;

const stripScheme = (v) => String(v ?? '').replace(/^https?:\/\//i, '');
const now = new Date().toISOString();

const calPayload = calResponse.data ?? calResponse;
const calEventTypeId = calPayload.id ?? buildData.cal_event_type_id ?? '';
const bookingUrl = calPayload.bookingUrl ? stripScheme(calPayload.bookingUrl) : buildData.cal_link;
const calSuccess = !calResponse.error && (calPayload.id || calResponse.status === 'success' || calResponse.success === true);
const calError = calResponse.error?.message || calResponse.message || calPayload.message || (calSuccess ? '' : JSON.stringify(calResponse));

const adminSuccess = !adminResponse.error && (adminResponse.resourceId || adminResponse.kind);
const googleResourceId = adminResponse.resourceId ?? '';
const resourceCalendarEmail = adminResponse.resourceEmail ?? '';
const adminError = adminResponse.error?.message || (adminSuccess ? '' : JSON.stringify(adminResponse));

return [{
  json: {
    property_key: buildData.property_key,
    cal_event_type_id: String(calEventTypeId),
    cal_link: bookingUrl,
    cal_provisioning_status: calSuccess ? 'provisioned' : 'error',
    cal_last_synced_at: now,
    cal_sync_error: calSuccess ? '' : calError,
    google_resource_id: googleResourceId,
    resource_calendar_email: resourceCalendarEmail,
    provisioning_status: (calSuccess && adminSuccess) ? 'provisioned' : 'partial_error',
    provisioned_at: (calSuccess && adminSuccess) ? now : '',
    error_message: [calSuccess ? '' : `Cal.com: ${calError}`, adminSuccess ? '' : `Admin: ${adminError}`].filter(Boolean).join(' | '),
  }
}];

